// Minimal Gemini REST client with structured JSON output, retries, and model fallback.
// Server-only: the API key never reaches the browser.

const API = "https://generativelanguage.googleapis.com/v1beta/models";
const RETRYABLE = new Set([429, 500, 502, 503, 504]);

export class GeminiError extends Error {}

/**
 * @param {object} o
 * @param {string} o.apiKey
 * @param {string[]} o.models        tried in order; each gets `attemptsPerModel` tries on retryable errors
 * @param {string} o.system          system instruction
 * @param {string} o.prompt          user content
 * @param {object} o.schema          JSON Schema for the response
 * @param {string} [o.thinkingLevel] "low" | "medium" | "high"
 * @returns {Promise<{ data: any, model: string }>}
 */
export async function generateJson({
  apiKey,
  models,
  system,
  prompt,
  schema,
  thinkingLevel = "low",
  attemptsPerModel = 2,
  timeoutMs = 90_000,
  fetchImpl = fetch,
}) {
  if (!apiKey) throw new GeminiError("GEMINI_API_KEY is not set");
  const body = JSON.stringify({
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: {
      responseMimeType: "application/json",
      responseJsonSchema: schema,
      temperature: 0.7,
      ...(thinkingLevel && { thinkingConfig: { thinkingLevel } }),
    },
  });

  let lastError;
  for (const model of models) {
    for (let attempt = 1; attempt <= attemptsPerModel; attempt++) {
      let res;
      try {
        res = await fetchImpl(`${API}/${model}:generateContent`, {
          method: "POST",
          headers: { "x-goog-api-key": apiKey, "Content-Type": "application/json" },
          body,
          signal: AbortSignal.timeout(timeoutMs),
        });
      } catch (err) {
        lastError = new GeminiError(`${model}: ${err.name === "TimeoutError" ? "timed out" : "network error"}`);
        continue;
      }
      const json = await res.json().catch(() => null);
      if (!res.ok) {
        lastError = new GeminiError(`${model}: HTTP ${res.status} ${json?.error?.status ?? ""}`.trim());
        if (RETRYABLE.has(res.status)) {
          await new Promise((r) => setTimeout(r, 500 * attempt));
          continue;
        }
        break; // non-retryable (e.g. 404 retired model) → next model
      }
      const text = json?.candidates?.[0]?.content?.parts?.filter((p) => !p.thought).map((p) => p.text ?? "").join("");
      try {
        return { data: JSON.parse(text), model };
      } catch {
        lastError = new GeminiError(`${model}: response was not valid JSON (finish: ${json?.candidates?.[0]?.finishReason ?? "unknown"})`);
      }
    }
  }
  throw lastError ?? new GeminiError("no models configured");
}

// Turns a saved grocery profile into a structured meal plan via an LLM.
// The LLM only proposes meals and per-meal ingredients; all list maths
// (merging, pantry removal, exclusion checks) happens in consolidate.js.

import { generateJson } from "./gemini.js";

export const UNITS = ["g", "ml", "count"];
export const SLOTS = ["breakfast", "lunch", "dinner"];
export const CATEGORIES = ["produce", "meat-seafood", "dairy-eggs", "bakery", "pantry", "frozen", "tofu-plant-protein", "condiments-sauces", "other"];
export const MAX_ITEMS = 12;

export const PLAN_SCHEMA = {
  type: "object",
  properties: {
    meals: {
      type: "array",
      items: {
        type: "object",
        properties: {
          day: { type: "integer", description: "1-based day number" },
          slot: { type: "string", enum: SLOTS },
          name: { type: "string" },
          servings: { type: "integer" },
          prepMinutes: { type: "integer" },
          leftoversFromDay: { type: "integer", description: "If this meal is leftovers of an earlier cooked meal, that day number; otherwise 0" },
          ingredients: {
            type: "array",
            items: {
              type: "object",
              properties: {
                name: { type: "string", description: "Generic grocery product name to search for, e.g. 'chicken thighs', 'baby bok choy', 'jasmine rice'" },
                quantity: { type: "number" },
                unit: { type: "string", enum: UNITS },
                category: { type: "string", enum: CATEGORIES },
              },
              required: ["name", "quantity", "unit", "category"],
            },
          },
        },
        required: ["day", "slot", "name", "servings", "prepMinutes", "leftoversFromDay", "ingredients"],
      },
    },
    estimatedTotal: { type: "number", description: "Rough grocery cost in CAD for everything to buy" },
    summary: { type: "string", description: "One or two sentences describing the plan" },
  },
  required: ["meals", "estimatedTotal", "summary"],
};

const SYSTEM = `You are CartPilot's meal planner. You plan practical, budget-aware home meals for groceries bought at T&T Supermarket in Canada (a large Asian supermarket that also stocks everyday Western groceries).
Rules:
- Plan breakfast, lunch and dinner for every day requested, scaled to the household size.
- Reuse ingredients across meals and use leftovers so the shopping list stays short: at most ${MAX_ITEMS} distinct ingredients to buy, not counting pantry items.
- Ingredient names must be generic grocery products a shopper would search for (no brands, no preparation words like "diced").
- Quantities in metric: grams (g), millilitres (ml), or a count. Give the total amount the meal uses.
- Never include any allergen or avoided food the user lists, including as a minor ingredient. Respect the diet strictly.
- Assume salt, pepper, cooking oil and water are available. Include pantry items in recipes where useful (they will not be bought).
- Keep the estimated total within the budget; prefer cheaper staples when the budget is tight.
- The "User note" is the shopper's own request; follow it when it does not conflict with these rules.`;

export function buildPrompt(profile, note = "") {
  const list = (xs) => (xs?.length ? xs.join(", ") : "none");
  return [
    `Budget: $${profile.budget} CAD total`,
    `People: ${profile.householdSize}`,
    `Days: ${profile.shoppingDays}`,
    `Diet: ${profile.diet}`,
    `Cuisines they enjoy: ${list(profile.cuisines)}`,
    `Nutrition preferences: ${list(profile.nutritionPrefs)}`,
    `Cooking style: ${profile.cookingPref}`,
    `ALLERGIES (never include): ${list(profile.allergies)}`,
    `Foods/categories to avoid: ${list(profile.avoid)}`,
    `Already in pantry: ${list(profile.pantry)}`,
    "",
    `User note: ${note.trim() || "none"}`,
  ].join("\n");
}

/** Factory so the app can be tested with a fake planner. */
export function createGeminiPlanner({ apiKey, models, thinkingLevel }) {
  return async function plan(profile, note) {
    const { data, model } = await generateJson({
      apiKey,
      models,
      thinkingLevel,
      system: SYSTEM,
      prompt: buildPrompt(profile, note),
      schema: PLAN_SCHEMA,
    });
    return { ...data, model };
  };
}

// Deterministic shopping-list logic. Takes the LLM's per-meal ingredients and
// the user's profile; returns the list to buy, what the pantry covers, and
// warnings. No LLM involvement, so the numbers are predictable and testable.

import { MAX_ITEMS } from "./mealPlan.js";

const MEAT_FISH = ["chicken", "beef", "pork", "lamb", "turkey", "bacon", "ham", "sausage", "fish", "salmon", "tuna", "shrimp", "prawn", "cod", "tilapia", "crab", "squid", "anchov", "duck"];
const ANIMAL = [...MEAT_FISH, "egg", "milk", "cheese", "butter", "yogurt", "yoghurt", "cream", "honey", "gelatin"];
const PESCATARIAN_OK = ["fish", "salmon", "tuna", "shrimp", "prawn", "cod", "tilapia", "crab", "squid", "anchov"];

/** Lowercase, collapse spaces, naive singular. */
export function normalize(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .map(singular)
    .join(" ");
}

function singular(w) {
  if (w.length <= 3 || w.endsWith("ss")) return w;
  if (w.endsWith("ies")) return w.slice(0, -3) + "y";
  if (w.endsWith("oes")) return w.slice(0, -2);
  if (w.endsWith("s")) return w.slice(0, -1);
  return w;
}

/** True when every word of `term` appears in `name` (e.g. "soy sauce" ⊂ "dark soy sauce"). */
export function matchesTerm(name, term) {
  const words = new Set(normalize(name).split(" "));
  const t = normalize(term).split(" ").filter(Boolean);
  return t.length > 0 && t.every((w) => words.has(w));
}

function dietViolation(name, diet) {
  const n = normalize(name);
  const has = (list) => list.find((w) => n.split(" ").some((x) => x.startsWith(w)));
  if (diet === "vegan") return has(ANIMAL);
  if (diet === "vegetarian") return has(MEAT_FISH);
  if (diet === "pescatarian") {
    const hit = has(MEAT_FISH);
    return hit && !PESCATARIAN_OK.includes(hit) ? hit : undefined;
  }
  return undefined;
}

const round = (x, unit) => (unit === "count" ? Math.ceil(x * 100) / 100 : Math.round(x));

export function consolidate(plan, profile) {
  const warnings = [];
  const groups = new Map();

  for (const meal of plan.meals ?? []) {
    for (const ing of meal.ingredients ?? []) {
      if (!ing?.name || !(ing.quantity > 0)) continue;
      const key = normalize(ing.name);
      if (!key) continue;
      let g = groups.get(key);
      if (!g) {
        g = { key, name: ing.name.trim().toLowerCase(), category: ing.category ?? "other", amounts: {}, usedIn: [] };
        groups.set(key, g);
      }
      g.amounts[ing.unit] = (g.amounts[ing.unit] ?? 0) + ing.quantity;
      const label = `Day ${meal.day} ${meal.slot}: ${meal.name}`;
      if (!g.usedIn.includes(label)) g.usedIn.push(label);
    }
  }

  const toBuy = [];
  const pantryCovered = [];
  const removed = [];

  for (const g of groups.values()) {
    const item = {
      name: g.name,
      searchTerm: g.name,
      category: g.category,
      quantities: Object.entries(g.amounts).map(([unit, amount]) => ({ amount: round(amount, unit), unit })),
      usedIn: g.usedIn,
    };

    const allergen = profile.allergies.find((a) => matchesTerm(g.name, a));
    if (allergen) {
      removed.push({ ...item, reason: `matches allergy "${allergen}"` });
      warnings.push({ type: "allergy", message: `Removed "${g.name}": it matches your allergy "${allergen}". Check the meals that used it.` });
      continue;
    }
    const avoided = profile.avoid.find((a) => matchesTerm(g.name, a));
    if (avoided) {
      removed.push({ ...item, reason: `matches "${avoided}" on your avoid list` });
      warnings.push({ type: "avoid", message: `Removed "${g.name}": it's on your avoid list ("${avoided}").` });
      continue;
    }
    const dietHit = dietViolation(g.name, profile.diet);
    if (dietHit) {
      removed.push({ ...item, reason: `not ${profile.diet}` });
      warnings.push({ type: "diet", message: `Removed "${g.name}": not ${profile.diet}.` });
      continue;
    }
    const pantry = profile.pantry.find((p) => matchesTerm(g.name, p) || matchesTerm(p, g.name));
    if (pantry) {
      pantryCovered.push({ ...item, pantryItem: pantry });
      continue;
    }
    toBuy.push(item);
  }

  toBuy.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name));

  if (toBuy.length > MAX_ITEMS) {
    warnings.push({ type: "long-list", message: `The list has ${toBuy.length} items; the agent works best with ${MAX_ITEMS} or fewer. Consider removing some.` });
  }
  if (typeof plan.estimatedTotal === "number" && plan.estimatedTotal > profile.budget) {
    warnings.push({ type: "budget", message: `The planner's rough estimate ($${plan.estimatedTotal.toFixed(2)}) is over your $${profile.budget} budget. Real prices are checked in the next step.` });
  }
  if (profile.allergies.length) {
    warnings.push({ type: "allergy-check", message: "Allergy filtering is a screening aid only. Always check product labels yourself." });
  }

  return { toBuy, pantryCovered, removed, warnings };
}

